import sys
from pathlib import Path
_scripts = Path(__file__).resolve().parent
_root = _scripts.parent.parent
if str(_root) not in sys.path:
    sys.path.insert(0, str(_root))
from composeApp.scripts.categories_data import _qa, _meta

CITIES = ["Москва", "Санкт-Петербург", "Казань", "Новосибирск", "Екатеринбург", "Нижний Новгород",
          "Самара", "Ростов-на-Дону", "Воронеж", "Краснодар"]

def _extras(slug, start_num, start_date, items):
    """items: list of (article_slug, question, p1, p2)"""
    result = []
    for i, (art_slug, q, p1, p2) in enumerate(items):
        d = f"{int(start_date.split('.')[0])+i:02d}.{start_date.split('.')[1]}.{start_date.split('.')[2]}"
        result.append(_qa(art_slug, q, _meta(d, start_num + i, CITIES[i % 10]), p1, p2))
    return result

